+	Store       Store[A]
+	Resources   ResourceRegistry
+	Scopes      ScopePolicy[A]
+	Revalidator PrincipalRevalidator[A]
+	Tokens      TokenService[A]
+	Secrets     SecretSource
+	Clock       Clock
+	Audit       AuditSink
+}
+
+type Engine[A any] struct {
+	config Config
