+}
+
+type RegisterClientInput struct {
+	DisplayName     string
+	RedirectURIs    []string
+	RequestedScopes []string
+}
+
+type RegisterClientResult struct{ Client Client }
+
+type BeginAuthorizationInput struct {
+	ClientID        string
+	RedirectURI     string
