+// Package httptransport adapts oauthserver transitions to OAuth HTTP endpoints.
+package httptransport
+
+import (
+	"context"
+	"encoding/json"
+	"errors"
+	"html/template"
+	"io"
+	"net/http"
+	"net/url"
